import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './LandingPage.css';
import bcrypt from 'bcryptjs';

const projects = [
  {
    year: 2024,
    label: '2024',
    route: '/2024',
    description: 'Květinový svět',
  },
  {
    year: 2025,
    label: '2025',
    route: '/2025',
    description: 'Afirmační hra',
  },
];

const PASSWORD_HASH = '$2a$12$YKjfPQzFnUWxVA13Ecp.M.xZDiOfk3KL9uSYozKNCoMTtouCMwd9y'; // same as BirthdayPage

const LandingPage = () => {
  const [current, setCurrent] = useState(0);
  const [showModal, setShowModal] = useState(false);
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [pendingRoute, setPendingRoute] = useState(null);
  const [isMobile, setIsMobile] = useState(false);
  const startX = useRef(0);
  const navigate = useNavigate();

  // Check screen size on initial render and window resize
  useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth <= 768);
    };
    
    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  const handlePrev = () => {
    setCurrent((prev) => (prev === 0 ? projects.length - 1 : prev - 1));
  };
  
  const handleNext = () => {
    setCurrent((prev) => (prev === projects.length - 1 ? 0 : prev + 1));
  };

  const handleEnter = (route) => {
    setPendingRoute(route);
    setShowModal(true);
    setPassword('');
    setError('');
  };

  const handlePasswordSubmit = (e) => {
    e.preventDefault();
    if (bcrypt.compareSync(password, PASSWORD_HASH)) {
      setShowModal(false);
      setPassword('');
      setError('');
      navigate(pendingRoute);
    } else {
      setError('Špatné heslo, zkus to znovu.');
    }
  };

  // Touch events for swipe
  const handleTouchStart = (e) => {
    startX.current = e.touches[0].clientX;
  };

  const handleTouchEnd = (e) => {
    const endX = e.changedTouches[0].clientX;
    const diff = startX.current - endX;
    
    // Minimum swipe distance (px)
    const minSwipeDistance = 50;
    
    if (Math.abs(diff) > minSwipeDistance) {
      if (diff > 0) {
        // Swiped left - go to next
        handleNext();
      } else {
        // Swiped right - go to previous
        handlePrev();
      }
    }
  };

  return (
    <div className="landing-bg">
      <div className="carousel-container">
        {isMobile && (
          <button className="arrow-btn" onClick={handlePrev} aria-label="Předchozí">
            {'<'}
          </button>
        )}
        <div 
          className="cards-wrapper"
          onTouchStart={handleTouchStart}
          onTouchEnd={handleTouchEnd}
        >
          {isMobile ? (
            <div className="card mobile-card" key={projects[current].year}>
              <div className="card-content">
                <div className="card-label">{projects[current].label}</div>
                <div className="card-desc">{projects[current].description}</div>
                <button className="enter-btn" onClick={() => handleEnter(projects[current].route)}>
                  Vstoupit
                </button>
              </div>
            </div>
          ) : (
            projects.map((project, idx) => (
              <div className="card desktop-card" key={project.year}>
                <div className="card-content">
                  <div className="card-label">{project.label}</div>
                  <div className="card-desc">{project.description}</div>
                  <button className="enter-btn" onClick={() => handleEnter(project.route)}>
                    Vstoupit
                  </button>
                </div>
              </div>
            ))
          )}
        </div>
        {isMobile && (
          <button className="arrow-btn" onClick={handleNext} aria-label="Další">
            {'>'}
          </button>
        )}
      </div>
      {showModal && (
        <div className="landing-modal-bg">
          <div className="landing-modal">
            <h3>Zadej heslo</h3>
            <form onSubmit={handlePasswordSubmit}>
              <input
                type="password"
                className="landing-password-input"
                value={password}
                onChange={e => setPassword(e.target.value)}
                placeholder="Heslo"
                autoFocus
              />
              {error && <div className="landing-modal-error">{error}</div>}
              <div style={{marginTop: 16}}>
                <button className="enter-btn" type="submit">Potvrdit</button>
                <button className="enter-btn" type="button" style={{marginLeft: 8}} onClick={() => setShowModal(false)}>Zavřít</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default LandingPage; 