const SWIPE_THRESHOLD = 80;

const getSwipeColor = (x) => {
  if (x > 0) {
    const intensity = Math.min(Math.abs(x) / 120, 1);
    return `rgba(120, 200, 120, ${intensity * 0.35})`;
  } else if (x < 0) {
    const intensity = Math.min(Math.abs(x) / 120, 1);
    return `rgba(255, 80, 80, ${intensity * 0.35})`;
  }
  return 'transparent';
};

const SwipeCards = () => {
  const [cards, setCards] = useState(() => shuffleArray(initialCards));
  const [current, setCurrent] = useState(0);
  const [points, setPoints] = useState(0);
  const [showPopup, setShowPopup] = useState(false);
  const [drag, setDrag] = useState({ x: 0, y: 0, isDragging: false });
  const [animating, setAnimating] = useState(false);
  const [cardsUsed, setCardsUsed] = useState(0);
  const [showHistory, setShowHistory] = useState(false);
  const [history, setHistory] = useState([]);
  const [historyLoading, setHistoryLoading] = useState(false);
  const cardRef = useRef(null);
  const startX = useRef(0);
  const startY = useRef(0);
  const [showContactPopup, setShowContactPopup] = useState(false);



  // Fetch history from Supabase when history modal is opened
  useEffect(() => {
    if (showHistory) {
      setHistoryLoading(true);
      supabase
        .from('adelnarozeniny2025')
        .select('*')
        .order('date', { ascending: false })
        .then(({ data, error }) => {
          if (!error && data) {
            setHistory(data);
          }
          setHistoryLoading(false);
        });
    }
  }, [showHistory]);

  // Save to Supabase when game ends
  useEffect(() => {
    if (showPopup && cardsUsed > 0) {
      const newEntry = {
        date: new Date().toISOString(),
        cards_used: cardsUsed,
      };
      supabase.from('adelnarozeniny2025').insert([newEntry]).then();
    }
    // eslint-disable-next-line
  }, [showPopup]);

  const handleDragStart = (e) => {
    if (animating) return;
    setDrag(d => ({ ...d, isDragging: true }));
    if (e.type === 'touchstart') {
      startX.current = e.touches[0].clientX;
      startY.current = e.touches[0].clientY;
    } else {
      startX.current = e.clientX;
      startY.current = e.clientY;
      document.addEventListener('mousemove', handleDragMove);
      document.addEventListener('mouseup', handleDragEnd);
    }
  };

  function shuffleArray(arr) {
    const a = [...arr];
    for (let i = a.length - 1; i > 0; i--) {
         const j = Math.floor(Math.random() * (i + 1));
         [a[i], a[j]] = [a[j], a[i]];
       }
     return a;
    }

  const handleDragMove = (e) => {
    if (!drag.isDragging) return;
    let clientX, clientY;
    if (e.type === 'touchmove') {
      clientX = e.touches[0].clientX;
      clientY = e.touches[0].clientY;
    } else {
      clientX = e.clientX;
      clientY = e.clientY;
    }
    setDrag(d => ({ ...d, x: clientX - startX.current, y: clientY - startY.current }));
  };

  const handleDragEnd = (e) => {
    if (!drag.isDragging) return;
    let clientX;
    if (e.type === 'touchend') {
      clientX = e.changedTouches[0].clientX;
    } else {
      clientX = e.clientX;
      document.removeEventListener('mousemove', handleDragMove);
      document.removeEventListener('mouseup', handleDragEnd);
    }
    const deltaX = clientX - startX.current;
    if (deltaX > SWIPE_THRESHOLD) {
      animateSwipe('right');
    } else if (deltaX < -SWIPE_THRESHOLD) {
      animateSwipe('left');
    } else {
      setDrag({ x: 0, y: 0, isDragging: false });
    }
  };

  const animateSwipe = (direction) => {
    setAnimating(true);
    setDrag(d => ({ ...d, x: direction === 'right' ? 500 : -500 }));
    setTimeout(() => {
      setAnimating(false);
      setDrag({ x: 0, y: 0, isDragging: false });
      handleSwipe(direction === 'right' ? 1 : -1);
    }, 250);
  };

  const handleSwipe = (value) => {
    const newPoints = points + value;
    const newCardsUsed = cardsUsed + 1;
    if (newPoints >= 5) {
      setPoints(newPoints);
      setCardsUsed(newCardsUsed);
      setShowPopup(true);
    } else if (current === cards.length - 1) {
      setPoints(newPoints);
      setCardsUsed(newCardsUsed);
      setShowPopup(true);
    } else {
      setPoints(newPoints);
      setCardsUsed(newCardsUsed);
      setCurrent(current + 1);
    }
  };

  const handleRestart = () => {
    setCards(shuffleArray(initialCards));
      setCurrent(0);
      setPoints(0);
       setShowPopup(false);
      setDrag({ x: 0, y: 0, isDragging: false });
       setCardsUsed(0);
  };

  return (
    <div className="swipe-bg">
      <div className="swipe-container">
        <button className="history-btn" onClick={() => setShowHistory(true)}>
          Historie
        </button>
        {showHistory && (
            <div className="history-modal">
              <div className="history-modal-content">
                <h3>Historie tvých kartiček</h3>
                {historyLoading ? (
                    <div className="history-empty">Načítání...</div>
                ) : history.length === 0 ? (
                    <div className="history-empty">Zatím žádné záznamy.</div>
                ) : (
                    <ul className="history-list">
                      {history.map((entry, idx) => (
                          <li key={entry.id || idx} className="history-item">
                            <span className="history-date">{new Date(entry.date).toLocaleString()}</span>
                            <span className="history-cards">{entry.cards_used} karet</span>
                          </li>
                      ))}
                    </ul>
                )}
                <button className="history-close-btn" onClick={() => setShowHistory(false)}>
                  Zavřít
                </button>
              </div>
            </div>
        )}
        {showPopup ? (
            <div className="swipe-popup">
              <div className="swipe-popup-text">
                Dnes si zvládla afirmaci za {cardsUsed} karet. Seš moc skvělá, jako každý den:).
              </div>
              <button className="swipe-btn" onClick={handleRestart}>Zkusit znovu</button>
            </div>
        ) : (
            <div className="swipe-stack">
              {cards.slice(current).map((card, idx) => {
                if (idx > 1) return null;
                const isTop = idx === 0;
                const style = isTop
                    ? {
                      transform: `translate(${drag.x}px, ${drag.y}px) rotate(${drag.x / 12}deg)` + (animating ? ' scale(1.05)' : ''),
                      zIndex: 2,
                      transition: drag.isDragging || animating ? 'transform 0.25s cubic-bezier(.4,1.5,.5,1), box-shadow 0.2s' : 'box-shadow 0.2s',
                      boxShadow: drag.isDragging || animating ? '0 8px 32px rgba(178,108,108,0.18)' : '0 4px 16px rgba(178,108,108,0.12)',
                      background: getSwipeColor(drag.x),
                      aspectRatio: '9 / 16',
                      width: 'min(95vw, 340px)',
                      height: 'auto',
                      maxHeight: '80vh',
                    }
                    : {
                      transform: 'scale(0.96) translateY(12px)',
                      zIndex: 1,
                      filter: 'blur(4px)',
                      aspectRatio: '9 / 16',
                      width: 'min(95vw, 340px)',
                      height: 'auto',
                      maxHeight: '80vh',
                    };
                return (
                    <div
                        key={card.id}
                        className="swipe-card"
                        style={style}
                        ref={isTop ? cardRef : null}
                        onTouchStart={isTop ? handleDragStart : undefined}
                        onTouchMove={isTop ? handleDragMove : undefined}
                        onTouchEnd={isTop ? handleDragEnd : undefined}
                        onMouseDown={isTop ? handleDragStart : undefined}
                    >
                      <div className="swipe-card-text">{card.text}</div>
                      {isTop && (
                          <div className="swipe-actions">
                            <button className="swipe-btn no" onClick={() => animateSwipe('left')}>&#8592; Ne</button>
                            <button className="swipe-btn yes" onClick={() => animateSwipe('right')}>&#8594; Ano</button>
                          </div>
                      )}
                    </div>
                );
              })}
            </div>
        )}
        <button className="bottom-btn" onClick={() => setShowContactPopup(true)}>
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="currentColor" className="bi bi-envelope-heart" viewBox="0 0 16 16">
            <path fillRule="evenodd" d="M0 4a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H2a2 2 0 0 1-2-2zm2-1a1 1 0 0 0-1 1v.217l3.235 1.94a2.8 2.8 0 0 0-.233 1.027L1 5.384v5.721l3.453-2.124q.219.416.55.835l-3.97 2.443A1 1 0 0 0 2 13h12a1 1 0 0 0 .966-.741l-3.968-2.442q.33-.421.55-.836L15 11.105V5.383l-3.002 1.801a2.8 2.8 0 0 0-.233-1.026L15 4.217V4a1 1 0 0 0-1-1zm6 2.993c1.664-1.711 5.825 1.283 0 5.132-5.825-3.85-1.664-6.843 0-5.132"/>
          </svg>
        </button>

        {showContactPopup && (
            <div className="contact-popup-bg">
              <div className="contact-popup">
                <h3>Všechno nejlepší adél ❤️</h3>
                <p>Chtěl bych ti touto cestou popřát všechno nejlepší. Tento rok jsem bohužel vůbec nestíhal a tak jsem nevymyslel žádné originální hádanky:/
                  Chtěl jsem ti ale dát náhled do své diplomky. Tohle je taková malá afirmační hra. Musíš mít alespoň 5 bodů, aby si došla na konec. Taky je tam nějaká historie, takže se zpětně můžeš podívat, kolik kartiček si potřebovala v jaký den pro svou afirmaci:).
                Je tam nějaká menší báze otázek, kterou jsem vymýšlel, snad se nebudou často opakovat. Doufám, že se máš teď co nejlépe a taky doufám, že se brzy zase někdy potkáme a popovídáme si:).
                I love you </p>
                <button className="popup-close-btn" onClick={() => setShowContactPopup(false)}>Zavřít</button>
              </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default SwipeCards;
